 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture as textureNode, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find(i => i.role === 'headline') || items[0];

  const atlas = config.atlasRegion ?? { sourceRect: [0, 0, 512, 320] };
  const [, , rw, rh] = atlas.sourceRect;
  const aspect = (rw || 1) / (rh || 1);
  const width = 2.0;
  const height = width / aspect;

  const group = new THREE.Group();

  const cardGeo = new THREE.PlaneGeometry(width, height);
  const cardMat = new MeshBasicNodeMaterial({ color: colors.surface });
  cardMat.side = THREE.FrontSide;
  const card = new THREE.Mesh(cardGeo, cardMat);
  group.add(card);

  const edgeGeo = new THREE.PlaneGeometry(width + 0.08, height + 0.08);
  const edgeMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0,
    depthWrite: false
  });
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.006;
  group.add(edge);

  let textObj = null;
  if (headline && ctx.fontAtlas) {
    textObj = ctx.fontAtlas.createText(String(headline.text), {
      fontSize: headline.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'center'
    });
    textObj.position.z = 0.025;
    group.add(textObj);
  }

  let cardTexture;
  if (config.imageUrl && ctx.textureLoader) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((loaded) => {
      cardTexture = loaded;
      cardTexture.colorSpace = THREE.SRGBColorSpace;
      cardMat.colorNode = textureNode(cardTexture, uv());
      cardMat.needsUpdate = true;
    });
  }

  const primitiveRuns = [];
  const cinematic = Array.isArray(config.cinematicPrimitives) ? config.cinematicPrimitives : [];
  for (const p of cinematic) {
    if (p?.name && typeof ctx.primitives?.[p.name] === 'function') {
      const run = ctx.primitives[p.name](group, p.params || {});
      if (run) primitiveRuns.push(run);
    }
  }

  let hoverTween, edgeTween, clickTween;

  function killActiveTweens() {
    if (hoverTween) { hoverTween.kill(); hoverTween = null; }
    if (edgeTween) { edgeTween.kill(); edgeTween = null; }
    if (clickTween) { clickTween.kill(); clickTween = null; }
  }

  group.userData.handlers = {
    hover: (payload) => {
      const active = payload?.active !== false;
      killActiveTweens();
      hoverTween = gsap.to(group.position, {
        z: active ? 0.15 : 0,
        duration: 0.4,
        ease: 'power2.out'
      });
      edgeTween = gsap.to(edgeMat, {
        opacity: active ? 0.85 : 0,
        duration: 0.25,
        ease: 'power2.out'
      });
    },
    click: (payload) => {
      killActiveTweens();
      clickTween = gsap.timeline({
        onComplete: () => {
          ctx.emit('hub-journal.select', { source: config.id, ...(payload || {}) });
        }
      });
      clickTween
        .to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(1.7)' })
        .to(group.scale, { x: 1, y: 1, duration: 0.22, ease: 'power2.out' });
    },
    focus: () => {
      if (edgeTween) edgeTween.kill();
      edgeTween = gsap.to(edgeMat, { opacity: 0.85, duration: 0.25, ease: 'power2.out' });
    },
    blur: () => {
      if (edgeTween) edgeTween.kill();
      edgeTween = gsap.to(edgeMat, { opacity: 0, duration: 0.25, ease: 'power2.out' });
    }
  };

  group.userData.cleanup = () => {
    killActiveTweens();
    for (const run of primitiveRuns) {
      if (typeof run.cleanup === 'function') run.cleanup();
      if (run.timeline && typeof run.timeline.kill === 'function') run.timeline.kill();
    }
    group.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) {
          o.material.forEach(m => m.dispose());
        } else {
          o.material.dispose();
        }
      }
    });
    if (cardTexture && typeof cardTexture.dispose === 'function') cardTexture.dispose();
    for (let i = group.children.length - 1; i >= 0; i--) {
      group.remove(group.children[i]);
    }
  };

  return group;
}
